fn hr_width_exact_factories_and_saved_deleted_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLHRElement,P=C.prototype,doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:hr');if(!(x instanceof C)||x.width!==''||doc.createElementNS('http://www.w3.org/1999/xhtml','HR') instanceof C||document.createElementNS('urn:foreign','hr') instanceof C)throw 'exact horizontal rule factory';delete window.HTMLHRElement;var y=document.createElement('HR');y.width='metadata';var copy=y.cloneNode(false);if(!(y instanceof C)||!(copy instanceof C)||Object.getPrototypeOf(y)!==P||y.localName!=='hr'||y.firstChild!==null||copy.width!=='metadata'||copy.getAttributeNode('width')===y.getAttributeNode('width'))throw 'saved horizontal rule canonical factory';");}

#[test]
fn hr_width_independent_alignment_attribute_keeps_actual_handle(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('para'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:hr')]){x.align='unchanged';var align=x.getAttributeNode('align');x.width='A\ud800Z';var attr=x.getAttributeNode('width'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.width={toString:function(){return 'unrestricted';}};var records=watch.takeRecords();if(x.align!=='unchanged'||x.getAttributeNode('align')!==align||align.value!=='unchanged'||x.getAttributeNode('width')!==attr||attr.value!=='unrestricted'||records.length!==1||records[0].attributeName!=='width'||records[0].oldValue!=='A\ud800Z')throw 'independent actual separator attributes';x.removeAttribute('width');if(x.width!==''||x.align!=='unchanged'||x.getAttributeNode('align')!==align||attr.ownerElement!==null)throw 'independent width removal';watch.takeRecords();var calls=0;x.width={toString:function(){calls++;x.align='author effect';return 'new width';}};records=watch.takeRecords();if(calls!==1||x.align!=='author effect'||align.value!=='author effect'||x.getAttributeNode('align')!==align||x.width!=='new width'||x.getAttributeNode('width')===attr||records.length!==2||records[0].attributeName!=='align'||records[1].attributeName!=='width'||records[1].oldValue!==null)throw 'independent author conversion effect';}"#);}

#[test]
fn hr_width_string_metadata_preserves_color_no_shade_and_author_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('para'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:hr')]){x.color='original';x.noShade=true;var color=x.getAttributeNode('color'),shade=x.getAttributeNode('noshade'),old=x.getAttribute('width'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.width=42;var width=x.getAttributeNode('width'),records=watch.takeRecords();if(typeof x.width!=='string'||x.width!=='42'||records.length!==1||records[0].attributeName!=='width'||records[0].oldValue!==old||x.color!=='original'||x.getAttributeNode('color')!==color||x.noShade!==true||x.getAttributeNode('noshade')!==shade)throw 'width string conversion and independent actual attributes';var calls=0;x.width={toString:function(){calls++;x.color='author effect';return '-0007% arbitrary';}};records=watch.takeRecords();if(calls!==1||x.width!=='-0007% arbitrary'||x.getAttributeNode('width')!==width||x.color!=='author effect'||color.value!=='author effect'||x.getAttributeNode('color')!==color||x.getAttributeNode('noshade')!==shade||shade.value!==''||x.noShade!==true||records.length!==2||records[0].attributeName!=='color'||records[1].attributeName!=='width'||records[1].oldValue!=='42')throw 'unparsed width and current author effects';x.removeAttribute('width');if(x.width!==''||width.ownerElement!==null||width.value!=='-0007% arbitrary'||x.color!=='author effect'||x.getAttributeNode('noshade')!==shade)throw 'width removal keeps neighboring metadata';}"#);}

#[test]
fn hr_width_string_reflection_keeps_actual_size_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('para'),new Document().createElementNS('http://www.w3.org/1999/xhtml','hr')]){x.size='-0009% size';var size=x.getAttributeNode('size'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.width=Infinity;var width=x.getAttributeNode('width'),records=watch.takeRecords();if(typeof x.width!=='string'||x.width!=='Infinity'||x.size!=='-0009% size'||size.value!==x.size||x.getAttributeNode('size')!==size||records.length!==1||records[0].attributeName!=='width')throw 'independent width string conversion';x.width='  -002% arbitrary';records=watch.takeRecords();if(x.width!=='  -002% arbitrary'||width.value!==x.width||x.getAttributeNode('width')!==width||records.length!==1||records[0].oldValue!=='Infinity')throw 'unparsed width string';x.removeAttribute('width');if(x.width!==''||width.ownerElement!==null||width.value!=='  -002% arbitrary'||x.getAttributeNode('size')!==size||size.value!=='-0009% size')throw 'width removal keeps size';}"#);}
